BEGIN;
--
-- Create model ClientProfile
--
CREATE TABLE "clients_clientprofile" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "client_name" varchar(150) NOT NULL, "spouse_name" varchar(150) NOT NULL, "phone" varchar(15) NOT NULL, "email" varchar(254) NOT NULL, "address" text NOT NULL, "plan_date" date NULL, "advisor_notes" text NOT NULL, "client_id" bigint NOT NULL UNIQUE);
--
-- Create model FamilyMember
--
CREATE TABLE "clients_familymember" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "position" smallint NOT NULL CHECK ("position" >= 0), "name" varchar(150) NOT NULL, "relationship" varchar(20) NOT NULL, "date_of_birth" date NULL, "age" smallint NULL CHECK ("age" >= 0), "gender" varchar(10) NOT NULL, "occupation" varchar(100) NOT NULL, "annual_income" numeric(14, 2) NOT NULL, "life_policy" varchar(150) NOT NULL, "life_cover" numeric(16, 2) NOT NULL, "health_policy" varchar(150) NOT NULL, "health_cover" numeric(16, 2) NOT NULL, "is_dependent" boolean NOT NULL, "notes" varchar(255) NOT NULL, "client_id" bigint NOT NULL);
--
-- Create model InsuranceCover
--
CREATE TABLE "clients_insurancecover" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "income_replacement_years" smallint NOT NULL CHECK ("income_replacement_years" >= 0), "existing_life_cover" numeric(16, 2) NOT NULL, "existing_health_cover" numeric(16, 2) NOT NULL, "auto_sum_from_family" boolean NOT NULL, "client_id" bigint NOT NULL UNIQUE);
--
-- Create model AssetItem
--
CREATE TABLE "clients_assetitem" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "key" varchar(40) NOT NULL, "label" varchar(150) NOT NULL, "amount" numeric(14, 2) NOT NULL, "asset_class" varchar(30) NOT NULL, "purpose" varchar(100) NOT NULL, "client_id" bigint NOT NULL, CONSTRAINT "uniq_asset_item" UNIQUE ("client_id", "key"));
--
-- Create model ExpenseItem
--
CREATE TABLE "clients_expenseitem" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "key" varchar(40) NOT NULL, "label" varchar(150) NOT NULL, "amount" numeric(14, 2) NOT NULL, "category" varchar(30) NOT NULL, "client_id" bigint NOT NULL, CONSTRAINT "uniq_expense_item" UNIQUE ("client_id", "key"));
--
-- Create model IncomeItem
--
CREATE TABLE "clients_incomeitem" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "key" varchar(40) NOT NULL, "label" varchar(150) NOT NULL, "amount" numeric(14, 2) NOT NULL, "client_id" bigint NOT NULL, CONSTRAINT "uniq_income_item" UNIQUE ("client_id", "key"));
--
-- Create model InvestmentItem
--
CREATE TABLE "clients_investmentitem" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "key" varchar(40) NOT NULL, "label" varchar(150) NOT NULL, "amount" numeric(14, 2) NOT NULL, "client_id" bigint NOT NULL, CONSTRAINT "uniq_investment_item" UNIQUE ("client_id", "key"));
--
-- Create model LiabilityItem
--
CREATE TABLE "clients_liabilityitem" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "key" varchar(40) NOT NULL, "label" varchar(150) NOT NULL, "amount" numeric(14, 2) NOT NULL, "purpose" varchar(100) NOT NULL, "client_id" bigint NOT NULL, CONSTRAINT "uniq_liability_item" UNIQUE ("client_id", "key"));
ALTER TABLE "clients_clientprofile" ADD CONSTRAINT "clients_clientprofile_client_id_d22d31b9_fk_clients_client_id" FOREIGN KEY ("client_id") REFERENCES "clients_client" ("id") DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "clients_familymember" ADD CONSTRAINT "clients_familymember_client_id_5b8e9fe6_fk_clients_client_id" FOREIGN KEY ("client_id") REFERENCES "clients_client" ("id") DEFERRABLE INITIALLY DEFERRED;
